import sys
sys.path.insert(0,'/workspace/tmp')
from genfast import GenFast as Base
class GenVar(Base):
    def __init__(self,H,participants,roots,edge_mode='nat',root_mode='nat'):
        self.edge_mode=edge_mode
        # custom reorder roots dict insertion doesn't matter much; q sorted keys in base
        super().__init__(H,participants,roots)
        self.root_mode=root_mode
        if root_mode!='nat':
            # rebuild q priority? Base q deque of keys created sorted root; can reorder queue
            q=list(self.q)
            if root_mode=='rev':q.sort(key=lambda k:-k[0])
            elif root_mode=='demand_asc':q.sort(key=lambda k:(self.Cs[k],k[0]))
            elif root_mode=='demand_desc':q.sort(key=lambda k:(-self.Cs[k],k[0]))
            from collections import deque
            self.q=deque(q)
    def _ys(self,x):
        ys=list(self.Hadj[x].keys())
        if self.edge_mode=='cap_asc':ys.sort(key=lambda y:(self.Hadj[x].get(y,0),y))
        elif self.edge_mode=='cap_desc':ys.sort(key=lambda y:(-self.Hadj[x].get(y,0),y))
        elif self.edge_mode=='rev':ys.sort(reverse=True)
        else:ys.sort()
        return ys
    def generate(self):
        from collections import deque
        while self.q:
            key=self.q.popleft();root=self.roots_of[key]
            bfs=deque(sorted(self.Vs[key]))
            while bfs:
                x=bfs.popleft()
                for y in self._ys(x):
                    if y in self.Vs[key]:continue
                    if self.Hadj[x].get(y,0)<=0:continue
                    chunks=self.test_edge(key,x,y)
                    if chunks<=0:continue
                    bfs.append(y)
                    if chunks<self.Cs[key]:
                        nk=self.new_tree(root,self.Ts[key],self.Vs[key],self.Cs[key]-chunks)
                        self.Cs[key]=chunks
                    self.Ts[key].append((x,y));self.Vs[key].add(y)
                    c=self.Hadj[x][y]-chunks
                    if c==0:del self.Hadj[x][y]
                    else:self.Hadj[x][y]=c
            del self.active[key]
        return self.Ts,self.Cs
